package dev.aura.player;
import android.app.*;import android.content.*;import android.os.*;import android.net.wifi.WifiManager;import java.util.concurrent.*;
/** Keeps the phone relay alive while the local player is paused. */
public final class CastRelayService extends Service {
 private ListeningMonitor listening;private static CastRelayService instance;private static final int ID=206;private final ExecutorService commands=Executors.newSingleThreadExecutor();private NetworkPlayback owner;private PowerManager.WakeLock wake;private WifiManager.WifiLock wifi;private final Handler main=new Handler(Looper.getMainLooper());private final Runnable refresh=new Runnable(){public void run(){NetworkPlayback n=NetworkPlayback.instance;if(n==null||!n.relaying()){stopSelf();return;}getSystemService(NotificationManager.class).notify(ID,notice(n));main.postDelayed(this,2000);}};
 static void start(Context c){androidx.core.content.ContextCompat.startForegroundService(c,new Intent(c,CastRelayService.class));}
 static void finish(Context c){c.stopService(new Intent(c,CastRelayService.class));}
 static void refresh(){CastRelayService s=instance;if(s!=null)s.main.post(()->{NetworkPlayback n=NetworkPlayback.instance;if(n!=null)s.getSystemService(NotificationManager.class).notify(ID,s.notice(n));});}
 @Override public void onCreate(){super.onCreate();instance=this;getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("cast_relay","Wi-Fi 캐스트",NotificationManager.IMPORTANCE_LOW));wake=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"AURA:CastRelay");wake.acquire();try{WifiManager manager=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);wifi=manager.createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF,"AURA:CastRelay");wifi.acquire();}catch(RuntimeException optionalWifiLock){} }
 private PendingIntent command(String action){return PendingIntent.getService(this,action.hashCode(),new Intent(this,CastRelayService.class).setAction(action),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 private Notification notice(NetworkPlayback n){Track t=n.track();return new Notification.Builder(this,"cast_relay").setSmallIcon(R.drawable.ic_stat_aura).setContentTitle(t==null?"Wi-Fi 캐스트":t.title).setContentText("AURA · "+n.label()+" · 폰에서 음원을 중계하고 있습니다").setContentIntent(PendingIntent.getActivity(this,206,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).setOnlyAlertOnce(true).setOngoing(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"이전 곡",command("previous")).build()).addAction(new Notification.Action.Builder(n.playing()?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,n.playing()?"일시정지":"재생",command(n.playing()?"pause":"play")).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"캐스트 종료",command("disconnect")).build()).setStyle(new Notification.MediaStyle().setShowActionsInCompactView(0,1,2)).build();}
 @Override public int onStartCommand(Intent intent,int flags,int id){NetworkPlayback n=NetworkPlayback.instance;if(n==null){stopSelf();return START_NOT_STICKY;}owner=n;if(listening==null)listening=new ListeningMonitor(this,new ListeningMonitor.Source(){public Track track(){return n.track();}public long position(){return n.position();}public boolean playing(){return n.active()&&n.playing();}});startForeground(ID,notice(n));main.removeCallbacks(refresh);main.postDelayed(refresh,2000);String action=intent==null?null:intent.getAction();if("disconnect".equals(action)){try{if(n.isCast())n.command("stop");}catch(Exception ignored){}n.disconnect();stopSelf();}else if(action!=null){Runnable run=()->{try{n.command(action);}catch(Exception e){n.lastError=e.getMessage();}};if(n.isCast())run.run();else commands.execute(run);}return START_NOT_STICKY;}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public void onDestroy(){if(listening!=null)listening.close();instance=null;main.removeCallbacksAndMessages(null);commands.shutdownNow();if(wifi!=null&&wifi.isHeld())wifi.release();if(wake!=null&&wake.isHeld())wake.release();if(owner!=null)owner.close();super.onDestroy();}
}
